/**
 * Task manifests shipped inside the app (web-pwa/src/data/task-manifests.json, generated by
 * tools/cognitive-tasks/crawl-task-manifests.py). They are the fallback when a task folder publishes no
 * task-manifest.json of its own, so offline task copies work without any change on the server.
 * Keyed by the task folder's PATH, so one entry serves every host that carries the same tasks.
 */
import manifests from '../data/task-manifests.json' with { type: 'json' };
import type { TaskManifest } from './taskCache.ts';

export function bundledManifestFor(taskDir: string): TaskManifest | null {
  try {
    const m = (manifests as Record<string, TaskManifest>)[new URL(taskDir).pathname];
    return m ?? null;
  } catch { return null; }
}
